// Pre-renders the corpus with Pele's JavaScript bundle and writes standalone SVGs plus a
// manifest. `tests/prerendered.typ` embeds those files directly, so it exercises Pele's
// output without running CtxJS during Typst compilation.
//
//   bun tests/prerender.mjs
//
// The generated files are build artifacts and are not committed. They are regenerated by
// scripts/build-diagrams.sh and in CI before `tests/prerendered.typ` is compiled.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { render } from "../js/dist/pele.mjs";

const tests = path.dirname(fileURLToPath(import.meta.url));
const root = path.dirname(tests);
const outDir = path.join(tests, "prerendered");

// Mirrors the `modern` preset in lib.typ. Rendering is pinned to an embedded font so the
// SVGs do not depend on the host's installed fonts.
const theme = {
  bg: "#ffffff",
  "label-bg": "#ffffff",
  fg: "#1f2328",
  muted: "#59636e",
  line: "#59636e",
  border: "#1f2328",
  surface: "#f6f8fa",
  "surface-alt": "#eaeef2",
  accent: "#0969da",
  critical: "#cf222e",
  error: "#cf222e",
  "fg-on-light": "#1f2328",
  "fg-on-dark": "#ffffff",
  "series-1": "#0969da",
  "series-2": "#1a7f37",
  "series-3": "#9a6700",
  "series-4": "#cf222e",
  "series-5": "#8250df",
  "series-6": "#bf3989",
  "series-7": "#0550ae",
  "series-8": "#116329",
  font: "'Libertinus Serif', sans-serif",
  "font-mono": "'DejaVu Sans Mono', 'Liberation Mono', Consolas, monospace",
  stroke: "1.75px",
  radius: "6px",
  "title-weight": "bold",
  "heading-weight": "bold",
  "bold-weight": "bold",
};

const corpusDir = path.join(tests, "corpus");
const sources = [];
for (const file of fs.readdirSync(corpusDir).filter((f) => f.endsWith(".mmd")).sort()) {
  sources.push({ name: path.basename(file, ".mmd"), file: path.join("corpus", file) });
}
const realWorldDir = path.join(corpusDir, "real-world");
for (const file of fs.readdirSync(realWorldDir).filter((f) => f.endsWith(".mmd")).sort()) {
  const base = path.basename(file, ".mmd");
  sources.push({ name: `real-world-${base}`, file: path.join("corpus", "real-world", file) });
}

fs.rmSync(outDir, { recursive: true, force: true });
fs.mkdirSync(outDir, { recursive: true });

const manifest = [];
for (const { name, file } of sources) {
  const source = fs.readFileSync(path.join(tests, file), "utf8");
  const result = render(source, { measure: "auto" }, theme);
  if (!result.ok) {
    throw new Error(`${file}: ${result.code}: ${result.message}`);
  }
  const svgFile = `${name}.svg`;
  fs.writeFileSync(path.join(outDir, svgFile), result.svg);
  manifest.push({
    name,
    file: svgFile,
    source: file,
    type: result.type,
    width: Math.round(result.width * 100) / 100,
    height: Math.round(result.height * 100) / 100,
  });
  console.log(`${svgFile} ${result.type} ${result.width}×${result.height}`);
}

fs.writeFileSync(path.join(outDir, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
console.log(`wrote ${manifest.length} pre-rendered diagrams to ${path.relative(root, outDir)}`);
